        <div className="container mt-5 p-5">
            <div className="row">
                <div className="col-6">
                    <h1>{productName}</h1>
                    <p>{productDescription}</p>
                    <div>
                        <a href={learnMore} style={{ marginLeft: "110px", fontSize: "16px", textDecoration: "none" }}>Learn More <i class="fa fa-long-arrow-right"></i>
                        </a>
                    </div>
                </div>
                <div className="col-6">
                    <img src=""/>
                </div>
            </div>
        </div >
    );
}

